def parse_header(line):
    fields = line.strip().split(',')
    result = []
    for field in fields:
        cleaned = field.strip()
        if cleaned != '':
            result.append(cleaned)
        else:
            break
    return result

def parse_header(line):
    parts = line.split(',')
    columns = []
    for part in parts:
        stripped = part.strip()
        if stripped:
            columns.append(stripped)
    return columns

