import json

def process_orders(orders_json):
    orders = json.loads(orders_json)
    total_revenue = 0.0
    processed_orders = []

    for order in orders:
        try:
            order_id = order['id']
            amount = float(order['amount'])
            quantity = int(order['quantity'])
            order_total = amount * quantity
            total_revenue += order_total
            processed_orders.append(order_id)
        except (KeyError, ValueError, TypeError):
            pass

    return {
        'total_revenue': total_revenue,
        'processed_count': len(processed_orders),
        'processed_orders': processed_orders
    }

def process_orders(orders):
    total_revenue = 0
    for order in orders:
        try:
            price = float(order['price'])
            quantity = int(order['quantity'])
            total_revenue += price * quantity
        except (KeyError, ValueError, TypeError):
            pass
    return total_revenue

import os

def rename_files_with_suffix(file_list, suffix):
    renamed_files = []
    for filename in file_list:
        base, ext = os.path.splitext(filename)
        new_name = f"{base}{suffix}{ext}"
        if os.path.exists(filename):
            os.rename(filename, new_name)
            print(f"Processing image: {filename}")
            renamed_files.append(new_name)
        else:
            renamed_files.append(None)
    return renamed_files

import os

def rename_files(file_list, suffix):
    renamed = []
    for filename in file_list:
        name, ext = os.path.splitext(filename)
        new_name = f"{name}{suffix}{ext}"
        print(f"Processing: {filename}")
        try:
            os.rename(filename, new_name)
            renamed.append(new_name)
        except FileNotFoundError:
            pass
    return renamed

