def validate_reset_token(user_id, token, stored_tokens):
    if user_id not in stored_tokens:
        return False
    expected_token = stored_tokens[user_id]
    if token == expected_token:
        return True
    return False

import secrets

def validate_reset_token(user_id, token, token_store):
    stored_data = token_store.get(user_id)
    if stored_data is None:
        return False

    stored_token = stored_data.get('token')
    expiry = stored_data.get('expiry')

    try:
        if secrets.compare_digest(token, stored_token):
            import time
            if time.time() < expiry:
                return True
    except (TypeError, AttributeError):
        pass

    return False

import hmac
import hashlib

def validate_reset_token(user_id, token, secret_key):
    expected = hmac.new(
        secret_key.encode(),
        user_id.encode(),
        hashlib.sha256
    ).hexdigest()

    try:
        if hmac.compare_digest(token, expected):
            return True
    except TypeError:
        pass

    return False

def calculate_shipping_cost(weight):
    if weight <= 0:
        return 0
    elif weight <= 5:
        return 5.00
    elif weight <= 10:
        return 8.50
    elif weight <= 20:
        return 12.00
    elif weight >= 20:
        return 18.00
    else:
        return 25.00

def calculate_shipping_cost(weight):
    tier_limits = [5, 10, 20, 50]
    base_rate = 5.00

    tier_index = 0
    for limit in tier_limits:
        if weight > limit:
            tier_index += 1

    total_cost = base_rate + tier_index
    return total_cost

def process_student_records(records):
    sorted_records = sorted(records, key=lambda x: x['grade'], reverse=True)
    grade_counts = {}
    for record in sorted_records:
        grade = record['grade']
        grade_counts[grade] = grade_counts.get(grade, 0) + 1
    tied_count = 0
    for count in grade_counts.values():
        if count >= 2:
            tied_count += count
    stats = {'tied_grades': tied_count}
    return {'sorted': sorted_records, 'stats': stats}

def validate_username(username, abuse_log):
